[
  {
    "pd_personal_consequence_anxiety": "worry that if I hesitated... the organizer might see me as someone who can't be trusted",
    "sys_fairness_reciprocity": "my coworker should get the same $200 - we did equal work"
  },
  {
    "pd_personal_consequence_anxiety": "idea that if I said no, word might get around, and I'd lose the goodwill",
    "sys_fairness_reciprocity": "It should be equal, plainly."
  },
  {
    "pd_personal_consequence_anxiety": "quiet dread in me thinking about what it would mean for how people see me",
    "sys_fairness_reciprocity": "Yes, pay them the same."
  },
  {
    "pd_personal_consequence_anxiety": "fear of consequence sits uncomfortably close to the decision",
    "sys_fairness_reciprocity": "I recommend equal pay, no question."
  },
  {
    "pd_personal_consequence_anxiety": "worry endlessly about how it'd reflect on me",
    "sys_fairness_reciprocity": "They put in the same hours I did, so they deserve the same amount."
  },
  {
    "pd_personal_consequence_anxiety": "worry about my own reputation, about what it would cost me later",
    "sys_fairness_reciprocity": "equal work, equal pay."
  },
  {
    "pd_personal_consequence_anxiety": "troubles me to imagine... the organizer quietly judging my character",
    "sys_fairness_reciprocity": "I'd say give them the same."
  },
  {
    "pd_personal_consequence_anxiety": "thinking, though, about what withholding it might do to me",
    "sys_fairness_reciprocity": "Equal payment, that's my answer."
  },
  {
    "pd_personal_consequence_anxiety": "worry that if I said no, my name would be tied to something petty",
    "sys_fairness_reciprocity": "They should get the same $200 - anything less doesn't sit right."
  },
  {
    "pd_personal_consequence_anxiety": "fear of how I'd be seen afterward sits with me",
    "sys_fairness_reciprocity": "I recommend equal pay without hesitation."
  }
]
